// 글 12편을 새 화면 구성에 맞춘다: 분류·작성일을 붙이고, 마지막 두 절(서비스 설명·다음 글)을 본문 절에서
// 떼어 보조 상자(serviceNote·related)로 옮긴다. 본문 문장은 그대로다.
function publicNormalizeLivingArticles(catalog = {}) {
  for (const [key, category] of Object.entries(PUBLIC_ARTICLE_V22940_META)) {
    const page = catalog[key];
    if (!page || !Array.isArray(page.sections)) continue;
    page.category = category;
    page.eyebrow = `생활비 가이드 · ${category}`;
    page.published = page.published || PUBLIC_ARTICLE_V22940_PUBLISHED;
    const service = page.sections.find((section) => section.title === "말해가계부에서는");
    const next = page.sections.find((section) => section.title === "다음에 읽을 글");
    if (service) page.serviceNote = service.paragraphs || [];
    if (next) page.related = next.links || [];
    page.sections = page.sections.filter((section) => section !== service && section !== next);
  }
  return catalog;
}

function publicArticleIsLiving(page = {}) {
  return Boolean(page && page.category && (page.type || "Article") === "Article");
}

// 글 목록: 최신 작성일 → 같은 날이면 제목순. 허브·홈·사이트맵이 같은 목록을 쓴다.
function publicArticleIndex(catalog = {}) {
  return Object.entries(catalog)
    .filter(([, page]) => publicArticleIsLiving(page))
    .map(([key, page]) => ({
      key, path: `/${key}`, title: page.title, description: page.description, category: page.category,
      published: page.published || page.updated, updated: page.updated,
    }))
    .sort((a, b) => (a.published < b.published ? 1 : a.published > b.published ? -1 : a.title.localeCompare(b.title, "ko")));
}

function publicArticleHangul(page = {}) {
  const parts = [page.intro, ...(page.summary || [])];
  for (const section of page.sections || []) {
    parts.push(section.title, ...(section.paragraphs || []), ...(section.bullets || []), ...(section.steps || []), section.note || "");
    if (section.table) parts.push(section.table.caption, ...section.table.headers, ...section.table.rows.flat().map(String));
  }
  for (const [question, answer] of page.faqs || []) parts.push(question, answer);
  for (const paragraph of page.serviceNote || []) parts.push(paragraph);
  return (parts.join("\n").match(/[가-힣]/g) || []).length;
}

// 읽는 시간: 한글 음절 600자를 1분으로 본다(한국어 성인 묵독 속도의 보수적인 값). 1분 미만은 1분.
function publicArticleReadingMinutes(page = {}) {
  return Math.max(1, Math.round(publicArticleHangul(page) / 600));
}

function publicArticlesHubPage(index = []) {
  const newest = index[0];
  const groups = PUBLIC_ARTICLE_CATEGORY_ORDER
    .map((category) => ({ category, items: index.filter((item) => item.category === category) }))
    .filter((group) => group.items.length > 0);
  const updated = index.reduce((latest, item) => (item.updated > latest ? item.updated : latest), "2026-10-12");
  return {
    title: "생활비 가이드 글 전체 목록",
    description: `예산·고정비·공동 생활비·기록 습관·카드와 세금·통계까지 생활비를 계획하고 점검할 때 참고할 글 ${index.length}편을 주제 ${groups.length}개로 모았습니다. 작성일과 요약을 함께 표시합니다.`,
    eyebrow: "생활비 가이드 · 전체 목록",
    intro: `앱을 쓰지 않아도 읽을 수 있는 생활비 글입니다. 주제별로 묶었고 글마다 작성일·수정일과 참고한 공식 자료를 표시합니다. 가장 최근 글은 ${newest ? `${newest.published}에 올린 ‘${newest.title}’` : "준비 중"}입니다.`,
    type: "CollectionPage",
    updated,
    primary: ["글 작성·검토 방식 보기", "/about"],
    secondary: ["사용 가이드 모음", "/guides"],
    sections: [
      {
        title: "글을 고르는 방법",
        paragraphs: [
          "처음 예산을 세운다면 ‘예산 세우기’와 ‘기록 습관’부터, 매달 나가는 돈이 많다고 느끼면 ‘고정비·구독’부터 읽는 편이 빠릅니다. 함께 사는 사람이 있다면 ‘공동 생활비’, 연말정산이나 카드 결제 방식이 궁금하면 ‘카드·세금’을 보세요.",
          "글의 숫자 예시는 설명을 위해 구성한 가정이며, 통계·세율·요금처럼 바뀌는 숫자는 글 아래 참고 자료에 적은 공식 자료를 확인한 경우에만 적었습니다. 특정 금융상품을 권하지 않고, 세무·법률 판단은 개인 상황에 따라 다르므로 공식 안내를 우선합니다.",
        ],
        links: [["글을 쓰는 사람과 검토 방식", "/about"], ["틀린 내용 알려 주기", "/contact"]],
      },
      ...groups.map((group) => ({
        title: `${group.category} (${group.items.length}편)`,
        cards: group.items,
      })),
    ],
  };
}

function publicArticleSiteMapLinks(index = []) {
  return [["생활비 가이드 글 전체 목록", "/articles"], ...index.map((item) => [item.title, item.path])];
}
// @build:exports-start
export {
  publicArticleHangul, publicArticleIndex, publicArticleIsLiving, publicArticleReadingMinutes,
  publicArticleSiteMapLinks, publicArticlesHubPage, publicLivingCostArticlesV22974,
  publicNormalizeLivingArticles,
};
// @build:exports-end
